import Foundation

/// Tips (spec §11 TIP-1…TIP-8): what the dialog links to, when Frame Job asks
/// by itself, what it remembers, and whose instance counts. Foundation only,
/// so a probe can run the rule against a clock of its own and the AppKit-free
/// export queue can be followed from here. The dialog is `TipsWindowController.swift`, the
/// editor's button `TipsToolbarButton.swift`, Settings' pane
/// `TipsSettingsPane.swift`.

/// The one address "Leave a Tip" opens (TIP-1). The page is the owner's.
enum TipsLink {
    static let url = "https://boppallewyn.com/frame-job/tips/"
}

/// What the schedule is decided from: the stored state, read at one moment.
struct TipsState: Equatable {
    /// When the first counted export succeeded; nil before one has.
    var firstExport: Date?
    /// How many exports have succeeded in a person's instance (TIP-4, TIP-8),
    /// whoever started them: the export card, an MCP client or the Assistant.
    var exports = 0
    /// When the automatic ask was last shown, or "Leave a Tip" last pressed.
    var lastAsked: Date?
    /// Settings ▸ Tips' toggle.
    var enabled = true
}

/// When the automatic ask is due (TIP-3). Pure: the state, a moment and a
/// calendar in, a Bool out.
enum TipsSchedule {
    static let firstAskDays = 30
    static let firstAskExports = 5
    static let skipMonths = 6

    /// The Gregorian calendar in the Mac's time zone as it is now, whatever
    /// calendar the person's Mac shows: "December" is its month 12.
    static func localCalendar() -> Calendar {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone.current
        return calendar
    }

    /// Off is never due. The first ask waits for `firstAskExports` exports
    /// and `firstAskDays` days since the first of them. After an ask, only a
    /// December is due, and not one whose 1 December 00:00 is less than
    /// `skipMonths` calendar months after the last ask.
    static func isDue(_ state: TipsState, now: Date, calendar: Calendar) -> Bool {
        guard state.enabled else { return false }
        guard let first = state.firstExport else { return false }
        guard state.exports >= firstAskExports else { return false }
        guard now.timeIntervalSince(first) >= Double(firstAskDays) * 86_400 else { return false }
        guard let last = state.lastAsked else { return true }
        guard calendar.component(.month, from: now) == 12 else { return false }
        let year = calendar.component(.year, from: now)
        guard
            let december = calendar.date(from: DateComponents(year: year, month: 12, day: 1)),
            let earliest = calendar.date(byAdding: .month, value: skipMonths, to: last)
        else { return false }
        return earliest <= december
    }
}

/// Settings ▸ Tips' toggle (TIP-5, TIP-6): on shows the editor's Tips button
/// and lets the automatic ask happen.
enum TipsSettings {
    /// Bool; absent = true.
    static let enabledKey = "FrameJobTips"

    /// Posted after the toggle is written, so every editor's Tips button
    /// follows it at once.
    static let didChangeNotification = Notification.Name("FrameJobTipsSettingsDidChange")

    static func isEnabled(in defaults: UserDefaults = .standard) -> Bool {
        defaults.object(forKey: enabledKey) == nil ? true : defaults.bool(forKey: enabledKey)
    }

    /// Writes the toggle and posts `didChangeNotification`.
    static func setEnabled(_ enabled: Bool, in defaults: UserDefaults = .standard) {
        defaults.set(enabled, forKey: enabledKey)
        NotificationCenter.default.post(name: didChangeNotification, object: nil)
    }
}

/// Whose instance this is (TIP-8). A scratch instance counts nothing and asks
/// nothing: one a proof or a test copy runs on a socket of its own, and the
/// app's code run in a bare executable (a probe, the offscreen harness).
/// Both export doors (`TipsWindowController.swift`) ask before they do
/// anything, so the rule is about the instance and not about who started the
/// export.
enum TipsInstance {
    /// Pure. A person's instance runs from an app bundle, with
    /// `RC_AGENT_SOCKET` unset or empty (`AgentServer.socketPlan`'s reading).
    /// MC-6 keeps every proof off the person's socket, so an instance a proof
    /// can reach is one it gave that variable. A relocated home is
    /// deliberately not asked about: macOS sets one in a sandboxed process.
    static func counts(environment: [String: String], bundleIdentifier: String?) -> Bool {
        guard bundleIdentifier != nil else { return false }
        guard (environment[AgentServer.socketEnvironmentKey] ?? "").isEmpty else { return false }
        return true
    }

    /// `counts` for a process: its environment and its bundle. The two are
    /// parameters so a probe, which has no bundle, can hand it one.
    static func ofProcess(
        environment: [String: String] = ProcessInfo.processInfo.environment, bundle: Bundle = .main
    ) -> Bool {
        counts(environment: environment, bundleIdentifier: bundle.bundleIdentifier)
    }

    /// This process's own answer, read once.
    static let isPersons: Bool = {
        #if FRAMEJOB_DEV_TOOLS
        if devStore != nil { return true }
        #endif
        return ofProcess()
    }()

    #if FRAMEJOB_DEV_TOOLS
    /// `-RCDevTipsSuite <name>`, a dev-only launch default (TIP-7): the
    /// counting keys are read and written in the named suite and not in the
    /// bundle's domain, AND the instance counts whatever its socket. One
    /// switch does both, so a proof's instance can never count into the real
    /// domain. The name must start with `devSuitePrefix`, the prefix
    /// `tools/proof/proof_defaults.py` owns and removes; any other value, or
    /// a suite that cannot be made, is named on stderr and ignored whole.
    static let devSuiteKey = "RCDevTipsSuite"
    static let devSuitePrefix = "framejob."

    /// The suite the switch names, or nil without it.
    static let devStore: UserDefaults? = {
        guard let name = UserDefaults.standard.string(forKey: devSuiteKey) else { return nil }
        guard name.hasPrefix(devSuitePrefix), let store = UserDefaults(suiteName: name) else {
            let line = "\(devSuiteKey) must name a suite starting \"\(devSuitePrefix)\" (got "
                + "\"\(name)\"); Tips keeps the bundle's defaults and this instance's own rule.\n"
            FileHandle.standardError.write(Data(line.utf8))
            return nil
        }
        return store
    }()
    #endif
}

/// The stored state and its three writers (TIP-5). Every writer is reached
/// only in a person's instance (`TipsInstance`): an export that succeeded,
/// whoever started it, or the dialog's "Leave a Tip". Main thread.
final class TipsAsk {
    /// Int; absent = 0.
    static let exportsKey = "FrameJobTipsExports"
    /// A date, stamped by the first counted export and never again.
    static let firstExportKey = "FrameJobTipsFirstExport"
    /// A date: the last automatic ask, or the last press of "Leave a Tip".
    static let lastAskedKey = "FrameJobTipsLastAsked"

    /// The app's own, over the bundle's defaults and the real clock; under
    /// the dev-only `-RCDevTipsSuite`, over that suite.
    static let shared: TipsAsk = {
        #if FRAMEJOB_DEV_TOOLS
        if let store = TipsInstance.devStore { return TipsAsk(defaults: store) }
        #endif
        return TipsAsk()
    }()

    private let defaults: UserDefaults
    private let now: () -> Date
    private let calendar: () -> Calendar

    init(
        defaults: UserDefaults = .standard, now: @escaping () -> Date = { Date() },
        calendar: @escaping () -> Calendar = { TipsSchedule.localCalendar() }
    ) {
        self.defaults = defaults
        self.now = now
        self.calendar = calendar
    }

    var state: TipsState {
        TipsState(
            firstExport: defaults.object(forKey: Self.firstExportKey) as? Date,
            exports: defaults.integer(forKey: Self.exportsKey),
            lastAsked: defaults.object(forKey: Self.lastAskedKey) as? Date,
            enabled: TipsSettings.isEnabled(in: defaults))
    }

    /// One more export has succeeded in a person's instance. Counts whatever
    /// the toggle says.
    func countExport() {
        let state = self.state
        defaults.set(state.exports + 1, forKey: Self.exportsKey)
        if state.firstExport == nil { defaults.set(now(), forKey: Self.firstExportKey) }
    }

    /// True when the automatic ask is due now, and then it is recorded as
    /// asked, so the caller shows the dialog and a second call answers false.
    func takeAsk() -> Bool {
        let moment = now()
        guard TipsSchedule.isDue(state, now: moment, calendar: calendar()) else { return false }
        defaults.set(moment, forKey: Self.lastAskedKey)
        return true
    }

    /// "Leave a Tip" was pressed, from any door: that is an ask too.
    func noteTipPageOpened() {
        defaults.set(now(), forKey: Self.lastAskedKey)
    }
}

/// Which export queue jobs count (TIP-4): a person's Add to Queue and the
/// agent's `export`, followed by id as `AgentExports` follows the agent's, so
/// the queue's jobs carry no origin. `settle()` runs on every change of the
/// queue.
final class TipsQueueFollower {
    private let state: (UInt64) -> ExportQueueController.State?
    private let completed: () -> Void
    private(set) var followed: Set<UInt64> = []

    init(state: @escaping (UInt64) -> ExportQueueController.State?, completed: @escaping () -> Void)
    {
        self.state = state
        self.completed = completed
    }

    func follow(_ id: UInt64) {
        followed.insert(id)
        settle()
    }

    /// A followed job that completed calls `completed` once and is dropped;
    /// one cancelled, failed or gone from the list is dropped; one waiting or
    /// running stays.
    func settle() {
        for id in followed.sorted() {
            switch state(id) {
            case .completed:
                followed.remove(id)
                completed()
            case .cancelled, .failed, nil:
                followed.remove(id)
            case .waiting, .running:
                break
            }
        }
    }
}

import AppKit

/// The Tips dialog (spec §11 TIP-1, TIP-2): who a tip funds, "Leave a Tip"
/// and "Not Now".
///
/// **A window and not a sheet, deliberately.** It has three doors — the
/// editor's Tips button, Settings' Tips button and the automatic ask — and
/// two of them have no document to hold a sheet. It is modal to nothing, so
/// no window and no tool call ever waits on it. `SettingsWindowController`'s
/// mould: one instance, not released when closed, no frame autosave name.
/// It is built from the sheets' own pieces so it reads as one of them, and
/// it is left out of the Window menu because both buttons reopen it.
///
/// **Two ways to show it.** `show()` is a person's press: key and front, and
/// it writes nothing. `showAutomatic()` is the ask Frame Job makes by itself
/// (TIP-4): front WITHOUT key, so a Return typed into the editor can never
/// press "Leave a Tip". The two order calls are closures because a probe's
/// window is never key and could not tell the two apart otherwise.
///
/// **What "Leave a Tip" does.** Opens `TipsLink.url` in the browser, records
/// the press as an ask (TIP-5) and closes. Nothing here knows whether anyone
/// tipped.
final class TipsWindowController: NSWindowController {
    /// The app's one Tips dialog. A probe builds its own.
    static let shared = TipsWindowController()

    static let windowTitle = "Tips"
    static let heading = "Frame Job is free and open source"
    static let body =
        "Frame Job is made by one developer. It is free to use and its source is open. If it "
        + "is useful to you, a tip helps pay for the time to keep working on it. Tips are "
        + "voluntary, and nothing in Frame Job is locked without one."
    static let hint = "You can turn this reminder off in Frame Job ▸ Settings… ▸ Tips."
    static let notNowTitle = "Not Now"
    static let tipTitle = "Leave a Tip"

    private let ask: TipsAsk
    private let open: (URL) -> Void
    private let orderKey: (NSWindow) -> Void
    private let orderFront: (NSWindow) -> Void

    private(set) var notNowButton: NSButton!
    private(set) var tipButton: NSButton!

    init(
        ask: TipsAsk = .shared,
        open: @escaping (URL) -> Void = { NSWorkspace.shared.open($0) },
        orderKey: @escaping (NSWindow) -> Void = { $0.makeKeyAndOrderFront(nil) },
        orderFront: @escaping (NSWindow) -> Void = { $0.orderFront(nil) }
    ) {
        self.ask = ask
        self.open = open
        self.orderKey = orderKey
        self.orderFront = orderFront
        let window = NSWindow(
            contentRect: NSRect(x: 0, y: 0, width: sheetWidth, height: 240),
            styleMask: [.titled, .closable], backing: .buffered, defer: false)
        window.title = Self.windowTitle
        window.isReleasedWhenClosed = false
        window.isExcludedFromWindowsMenu = true
        super.init(window: window)
        let content = buildContent()
        window.contentView = content
        window.setContentSize(content.fittingSize)
        window.center()
        applyBackground()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("TipsWindowController does not support NSCoder")
    }

    private func buildContent() -> NSView {
        let width = sheetWidth - sheetInset * 2
        let bodyLabel = NSTextField(wrappingLabelWithString: Self.body)
        bodyLabel.font = DS.sans(13)
        bodyLabel.textColor = DS.textStrong
        bodyLabel.preferredMaxLayoutWidth = width
        bodyLabel.setAccessibilityIdentifier("tips.body")

        let hintLabel = NSTextField(wrappingLabelWithString: Self.hint)
        hintLabel.font = DS.sans(12)
        hintLabel.textColor = DS.textMuted
        hintLabel.preferredMaxLayoutWidth = width
        hintLabel.setAccessibilityIdentifier("tips.hint")

        notNowButton = StickerButton(
            title: Self.notNowTitle, style: .secondary, target: self,
            action: #selector(notNowClicked(_:)))
        notNowButton.setAccessibilityIdentifier("tips.notnow")
        tipButton = StickerButton(
            title: Self.tipTitle, style: .primary, target: self,
            action: #selector(tipClicked(_:)))
        tipButton.setAccessibilityIdentifier("tips.tip")

        return makeSheetView(
            title: Self.heading, content: sheetColumn([bodyLabel, hintLabel]),
            buttonRow: makeButtonRow(cancel: notNowButton, apply: tipButton))
    }

    private func applyBackground() {
        window?.backgroundColor = DS.chromeBackground
        window?.contentView?.layer?.backgroundColor = DS.chromeBackground.cgColor
    }

    // MARK: - Showing

    /// A person's press of a Tips button: key and front. Writes nothing.
    func show() {
        guard let window else { return }
        applyBackground()
        orderKey(window)
    }

    /// The ask Frame Job makes by itself: front, never key (TIP-4).
    func showAutomatic() {
        guard let window else { return }
        applyBackground()
        orderFront(window)
    }

    // MARK: - Buttons

    @objc func notNowClicked(_ sender: Any?) {
        close()
    }

    @objc func tipClicked(_ sender: Any?) {
        if let url = URL(string: TipsLink.url) { open(url) }
        ask.noteTipPageOpened()
        close()
    }
}

// MARK: - The export doors

/// The two places an export reaches Tips (TIP-4): the Export… sheet's success
/// and a queued job, which is a person's Add to Queue
/// (`EditorViewController+Export.swift`) or the agent's `export`
/// (`AgentServer+Export.swift`, the Assistant's too). Both doors do nothing in
/// a scratch instance (`counts`, TIP-8). The ask, the dialog, the queue and
/// that rule are parameters so a probe runs the doors on its own. Main thread.
final class TipsDoors {
    static let shared = TipsDoors()

    private let ask: TipsAsk
    private let dialog: () -> TipsWindowController
    private let queue: ExportQueueController
    private let counts: () -> Bool
    private var follower: TipsQueueFollower?
    private var queueObserver: NSObjectProtocol?
    /// The result sheets still up after a counted success, each waiting for
    /// its window's sheet to end.
    private var sheetEnds: [TipsSheetEnd] = []

    init(
        ask: TipsAsk = .shared,
        dialog: @escaping () -> TipsWindowController = { TipsWindowController.shared },
        queue: ExportQueueController = .shared,
        counts: @escaping () -> Bool = { TipsInstance.isPersons }
    ) {
        self.ask = ask
        self.dialog = dialog
        self.queue = queue
        self.counts = counts
    }

    deinit {
        if let queueObserver { NotificationCenter.default.removeObserver(queueObserver) }
    }

    /// An Export… the person confirmed has succeeded: counted now. The ask
    /// waits until `window`'s sheet — the export's own result panel — ends,
    /// and one main-queue turn more so the sheet has left; with no sheet
    /// attached it is asked at once. Nothing in a scratch instance.
    func exportSucceeded(sheetOn window: NSWindow?) {
        guard counts() else { return }  // the Export… door
        ask.countExport()
        guard let window, window.attachedSheet != nil else {
            askIfDue()
            return
        }
        sheetEnds.append(
            TipsSheetEnd(window: window) { [weak self] watch in
                guard let self else { return }
                self.sheetEnds.removeAll { $0 === watch }
                self.askIfDue()
            })
    }

    /// A queued job, a person's Add to Queue or the agent's `export`:
    /// followed to its end by id. A completion counts and asks; a cancel or a
    /// failure does neither. Not followed at all in a scratch instance.
    func follow(queueJob id: UInt64) {
        guard counts() else { return }  // the queue door
        if follower == nil {
            follower = TipsQueueFollower(
                state: { [queue] in queue.job($0)?.state },
                completed: { [weak self] in
                    self?.ask.countExport()
                    self?.askIfDue()
                })
            queueObserver = NotificationCenter.default.addObserver(
                forName: ExportQueueController.didChangeNotification, object: queue, queue: nil
            ) { [weak self] _ in self?.follower?.settle() }
        }
        follower?.follow(id)
    }

    /// Shows the dialog when the schedule says so, recording the ask at the
    /// moment it is shown.
    private func askIfDue() {
        guard ask.takeAsk() else { return }
        dialog().showAutomatic()
    }
}

/// One wait for a window's sheet to end, then one main-queue turn.
private final class TipsSheetEnd: NSObject {
    private let then: (TipsSheetEnd) -> Void

    init(window: NSWindow, then: @escaping (TipsSheetEnd) -> Void) {
        self.then = then
        super.init()
        NotificationCenter.default.addObserver(
            self, selector: #selector(ended(_:)), name: NSWindow.didEndSheetNotification,
            object: window)
    }

    @objc private func ended(_ note: Notification) {
        NotificationCenter.default.removeObserver(self)
        DispatchQueue.main.async { self.then(self) }
    }
}

// MARK: - The command

/// The command half, at the foot of the file that owns the feature
/// (`SettingsWindowController.swift`'s precedent): a nil-target selector, so
/// the editor's Tips button resolves it through the responder chain.
extension AppDelegate {
    @objc func showTips(_ sender: Any?) {
        TipsWindowController.shared.show()
    }
}

import AppKit

extension AgentServer {

    // MARK: - Export

    /// `export` — ⌘E (`EditorViewController.exportProjectCommand` and
    /// `ExportSheetController`). The preset names the ENCODING — a container
    /// and a codec, nothing about size — and the size is the sheet's separate
    /// choice, in the Size popup's own vocabulary and defaulting as the popup
    /// does to its first row: the document's size, or an image format's cap.
    /// The CORE resolves both into concrete settings (`rc_export_settings`)
    /// that go to the same `Exporter.export` the sheet uses: there is exactly
    /// one writer, so an agent export and a menu export cannot disagree.
    ///
    /// Answers AT ONCE (spec §11 #326): every refusal is made here, before
    /// anything is queued — the arguments, the core's settings, the folder,
    /// the graphics gate, and the frame limit and same-shape rule
    /// (`Exporter.settingsRefusal`, #470) — and the export is then a job in the Export
    /// Queue, exactly as the sheet's Add to Queue makes one, answered as
    /// `{export_id, path, status}`. `export_status` follows the job and
    /// `cancel_export` stops it (`AgentServer+ExportStatus.swift`); a failure
    /// while writing comes back from there. The queue window is not shown.
    ///
    /// One argument is NOT a setting and never reaches the core:
    /// `burn_in_timecode` is a recipe option (`RecipeOptions`), read below
    /// beside the overrides it deliberately does not join.
    ///
    /// The finished job's answer carries the sound the file actually holds —
    /// its integrated loudness and true peak, measured on the way through —
    /// for every format that has any, whether `loudness_lufs` was asked for
    /// or not, and, with `stems` (the sheet's Stems popup, spec §11 AU-108),
    /// each stem file beside the mix.
    ///
    /// The job counts toward Tips when it completes, as a person's Add to
    /// Queue job does (spec §11 TIP-4), in a person's instance only (TIP-8).
    func exportProject(_ a: [String: Any]) throws -> String {
        try exportProject(a, tips: .shared)
    }

    /// `export` with the Tips doors as a parameter, so a probe runs the
    /// agent's door on its own (`tools/proof/tips_probe.swift`).
    func exportProject(_ a: [String: Any], tips: TipsDoors) throws -> String {
        // The clock `export_status`'s `elapsed` runs on, read before any check.
        let started = ProcessInfo.processInfo.systemUptime
        let presetID = try requiredString(a, "preset")
        let path = try requiredString(a, "path")
        let wholeProject = (try stringArg(a, "range") ?? "project").lowercased()
        guard ["project", "in_out"].contains(wholeProject) else {
            throw ToolError(
                message: "range must be \"project\" (the whole timeline) or \"in_out\" "
                    + "(the in/out range set_range set), not \"\(wholeProject)\".")
        }
        // The export sheet's burn-in checkbox — and read HERE rather than
        // into `overrides` below, which is the whole of the decision. A
        // recipe option changes the PICTURE, so it travels with the
        // description of the picture: `export_overrides.rs` ignores a key it
        // does not know, on purpose, so a `burn_in_timecode` posted through
        // `rc_export_settings` would vanish without a word and this tool
        // would report success on an un-burnt file. It goes to `Exporter`
        // beside the settings instead (`RecipeOptions`, `Exporter.export`),
        // which is also what reaches GIF and APNG — those never go through
        // `ExportWriter` at all.
        let options = RecipeOptions(burnInTimecode: try boolArg(a, "burn_in_timecode") ?? false)
        let prepared = try onMain {
            () throws -> (ProjectDocument, ReelProject, [UInt32: URL], ExportSettings, GraphicSet?)
            in
            let document = try self.target(a)
            guard document.project.duration > 0 else {
                throw ToolError(message: "There is nothing on the timeline to export.")
            }
            let settings = try self.exportSettings(
                a, on: document, preset: presetID, range: wholeProject)
            return (
                document, document.project, document.mediaURLs(), settings,
                GraphicRegistry.shared.snapshot(for: document.recipeKey)
            )
        }
        let (document, project, urls, settings, graphics) = prepared
        let url = try Self.requireFolder(
            of: Self.destinationURL(path, extension: Exporter.fileExtension(for: settings)))

        // The graphics gate, here rather than only in the writer: a module
        // that does not compile refuses the CALL, so nothing is queued that
        // could only fail (`Exporter.graphicsRefusal`, the writer's own gate).
        if let refusal = Exporter.graphicsRefusal(
            project: project, settings: settings, graphics: graphics)
        {
            throw ToolError(message: refusal.localizedDescription)
        }
        // The same, for the two rules the sheet shows in its readout (#470).
        if let refusal = Exporter.settingsRefusal(settings, project: project) {
            throw ToolError(message: refusal.localizedDescription)
        }
        let (id, status) = onMain { () -> (UInt64, String) in
            // The editor pauses before its own export so the player is not
            // decoding the same media; the agent's does the same.
            self.editor(document)?.playback.pause()
            let id = ExportQueueController.shared.enqueue(
                project: project, urls: urls, settings: settings, to: url, options: options,
                graphics: graphics)
            AgentExports.shared.track(
                id, settings: settings, burnInTimecode: options.burnInTimecode, started: started)
            tips.follow(queueJob: id)
            let word = ExportQueueController.shared.job(id).map {
                Self.exportStatusWord($0.state)
            }
            return (id, word ?? "queued")
        }
        return try jsonResult(["export_id": id, "path": url.path, "status": status])
    }

    /// The core's settings for `export`'s arguments, every override read as
    /// the sheet's popups spell it, and every refusal the tool's own. Main
    /// only. `range` is the call's `range`, already lower-cased.
    func exportSettings(
        _ a: [String: Any], on document: ProjectDocument, preset: String, range: String
    ) throws -> ExportSettings {
        // The Range popup of the export sheet, in the sheet's own terms:
        // "Whole project" is no override at all, "In/out range" is the
        // core's ONE nested `range` object (`export.rs`). The core snaps
        // it to the frame grid and clamps it to the project.
        var overrides: [String: Any] = [:]
        if range == "in_out" {
            guard let inOut = document.inOutRange, inOut.end > inOut.start else {
                throw ToolError(
                    message: "This project has no in/out range — set one with set_range "
                        + "{start, end}, or export with range \"project\".")
            }
            overrides["range"] = ["start": inOut.start, "duration": inOut.end - inOut.start]
        }
        // The sheet's Quality popup, in the core's own words: it resolves
        // a tier into these two keys and nothing else
        // (`ExportSheetController.overrides()`), so the agent spells them
        // the same way rather than re-deriving a rate from a tier name.
        // The core validates them — positive, u32 — and an unset key means
        // "the preset decides", which is what a nil bitrate already means
        // to the writer.
        if let video = try intArg(a, "video_bitrate") {
            overrides["video_bitrate"] = video
        }
        if let audio = try intArg(a, "audio_bitrate") {
            overrides["audio_bitrate"] = audio
        }
        // The sheet's Loudness popup, in the core's words again — and
        // through `doubleArg`, not `intArg`: −14.5 LUFS is a real request
        // and every one of these figures is a negative fraction. Neither
        // is validated here. `export_overrides.rs` owns the bounds
        // (−70…0 and −20…0) and names the offending value the way the
        // bitrate refusals do; either may come alone, the ceiling being
        // the master limiter's (spec §11 AU-27).
        // Restating a bound here would be a second spelling of it to
        // drift from the first.
        // The sheet sends both together and fixes the ceiling at
        // −1 dBTP; a caller that wants −0.3 or −2.0 says so here.
        if let target = try doubleArg(a, "loudness_lufs") {
            overrides["loudness_lufs"] = target
        }
        if let ceiling = try doubleArg(a, "peak_dbtp") {
            overrides["peak_dbtp"] = ceiling
        }
        // The sheet's Size popup: a row id, or "Custom…" as an explicit
        // [width, height]. Absent is no override at all, so the tool's
        // default and the sheet's are one code path in the core — the
        // document's size, or an image format's cap.
        if let size = try exportSizeArg(a, document.project, preset: preset) {
            overrides["width"] = size.width
            overrides["height"] = size.height
        }
        // The sheet's Dynamic Range popup (spec §11 HD-14 (c)), forwarded
        // unread: the core's reader and resolver own its three words, its
        // per-row defaults and both refusals, each in its own sentence.
        if let dynamicRange = a["dynamic_range"] {
            overrides["dynamic_range"] = dynamicRange
        }
        // The sheet's Speed popup (spec §11 CX-12 (2)), forwarded unread on the
        // same terms: the core reads the three words and refuses a row without one.
        if let speed = a["encoder_speed"] {
            overrides["encoder_speed"] = speed
        }
        // The sheet's Bit depth popup (spec §11 AU-29), forwarded unread on the
        // same terms: the core reads 16 or 24 and refuses a row without a depth.
        if let bits = a["audio_bits"] {
            overrides["audio_bits"] = bits
        }
        // The sheet's Stems popup (spec §11 AU-108), forwarded unread on the same
        // terms: the core reads "tracks" or "names", refuses a movie row, and refuses
        // a project with no track heard.
        if let stems = a["stems"] {
            overrides["stems"] = stems
        }
        do {
            return try ReelExport.settings(document.project, preset: preset, overrides: overrides)
        } catch {
            throw Self.coreRefusal(error)
        }
    }

    /// The file `export` writes for these arguments: the settings' own
    /// extension on `path`, so the assistant's question names what the tool
    /// will write (spec §11 AI-21 (c)). It throws what the tool would refuse.
    /// Main only, on the document the lane pinned.
    func exportDestination(_ a: [String: Any], on document: ProjectDocument) throws -> URL {
        let preset = try requiredString(a, "preset")
        let path = try requiredString(a, "path")
        let range = (try stringArg(a, "range") ?? "project").lowercased()
        let settings = try exportSettings(a, on: document, preset: preset, range: range)
        return Self.destinationURL(path, extension: Exporter.fileExtension(for: settings))
    }

    /// The `size` argument of `export`, in the Size popup's vocabulary: a row
    /// id resolved through the same `rc_export_sizes` the popup is built from
    /// (`document`, `preset`, `2160p`, `1440p`, `1080p`, `720p` — `ExportSize`
    /// in `ReelCore.swift` says what each means, and `core/src/export_size.rs`
    /// why every document lists every row), or the popup's "Custom…" as an
    /// explicit `[width, height]`. nil when absent, which is no override: the
    /// core's default for the preset.
    ///
    /// A value that is neither is refused by NAME, never read as absent — the
    /// rule every reader in `AgentServer+Arguments.swift` keeps, and the root
    /// `CLAUDE.md`'s: a value a handler cannot read is refused by name, never
    /// dropped. A `size` dropped in silence would export at the wrong size
    /// and report success. A custom
    /// size outside the sheet's own field range is refused the same way,
    /// where the sheet clamps: a tool has no field to clamp in view of the
    /// caller, and the sheet's reason — a mistyped digit must not reach the
    /// encoder as a 300 000-pixel frame — holds for a model's typo too.
    private func exportSizeArg(
        _ a: [String: Any], _ project: ReelProject, preset: String
    ) throws -> (width: Int, height: Int)? {
        guard let raw = a["size"], !(raw is NSNull) else { return nil }
        // The rows come first, whichever spelling follows: every refusal
        // below lists the ids from them rather than from a vocabulary
        // restated here, which could drift from the core's, and a preset the
        // core does not know is refused at this point in the same words
        // `exportProject` would use a call later.
        let rows: [ExportSize]
        do {
            rows = try ReelExport.sizes(project, preset: preset)
        } catch {
            throw Self.coreRefusal(error)
        }
        let ids = rows.map { $0.id }.joined(separator: ", ")
        if let id = raw as? String {
            guard let row = rows.first(where: { $0.id == id }) else {
                throw ToolError(
                    message: "No export size is called \"\(id)\" for \(preset). The sizes "
                        + "are: \(ids) — or pass [width, height].")
            }
            return (row.width, row.height)
        }
        if let array = raw as? [Any], array.count == 2 {
            let edges = array.compactMap(Self.wholeEdge)
            if edges.count == 2 {
                let range = ExportSheetController.sizeRange
                // Each refusal of a `size` offers the OTHER spelling: the
                // unknown-id one above names the custom form, and this one
                // names the rows, so a caller who meant a standard size and
                // reached for numbers has the ids in front of it.
                guard edges.allSatisfy(range.contains) else {
                    throw ToolError(
                        message: "A custom size must be \(range.lowerBound)…\(range.upperBound) "
                            + "px on each edge, not [\(edges[0]), \(edges[1])] — or pass a "
                            + "row: \(ids).")
                }
                return (edges[0], edges[1])
            }
        }
        throw ToolError(
            message: "size must be a row of the export sheet's Size popup — \(ids) — or "
                + "[width, height] in px, not \(Self.spelled(raw)).")
    }

    /// One edge of a custom size as a whole number, or nil for a value that
    /// is not one — which sends the whole `size` to the refusal that names
    /// it. The coercion `intArg` applies holds: a string spelling of a whole
    /// number is a JSON-typing slip, not a different request. A fraction is
    /// refused rather than truncated, since 1920.5 is not a width the caller
    /// can have meant. So is a boolean: JSON's `true` arrives as an
    /// `NSNumber` like any other and would read as 1 through it, and the
    /// Core Foundation type is the one thing that still tells `true` from
    /// `1`.
    private static func wholeEdge(_ value: Any) -> Int? {
        if let number = value as? NSNumber {
            guard CFGetTypeID(number) != CFBooleanGetTypeID() else { return nil }
            let real = number.doubleValue
            return real.isFinite && real == real.rounded() ? number.intValue : nil
        }
        return (value as? String).flatMap(Int.init)
    }

    /// A refusal from `rc_export_settings` or `rc_export_sizes` as the tool's
    /// error. The core's message passes through as it was, with one
    /// addition: an unknown preset id — the message that begins
    /// "unknown export preset", the same words from either call
    /// (`export.rs`) — gets the ids the table does take appended, because
    /// without them it is the one error a model cannot correct itself from,
    /// since nothing else lists the table. A refused bitrate or range keeps
    /// its own message alone: a list of presets under it would be a false
    /// lead.
    private static func coreRefusal(_ error: any Error) -> ToolError {
        let message = error.localizedDescription
        guard message.hasPrefix("unknown export preset") else {
            return ToolError(message: message)
        }
        let names = ReelExport.presets().map { $0.id }.joined(separator: ", ")
        return ToolError(message: "\(message). The presets are: \(names).")
    }

    /// A caller's value as it was spelled, for a refusal that names it: its
    /// JSON where it is JSON, its Swift description otherwise.
    private static func spelled(_ raw: Any) -> String {
        guard JSONSerialization.isValidJSONObject([raw]),
            let data = try? JSONSerialization.data(
                withJSONObject: raw, options: [.fragmentsAllowed]),
            let text = String(data: data, encoding: .utf8)
        else { return String(describing: raw) }
        return text
    }
}

